/* Main Wrapper - Upgraded to CSS Grid for fluid responsiveness */
.yg-features-bar {
    display: grid;
    /* Automatically creates 4, 2, or 1 column based on available space */
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 30px;
    background:#f6f6f6;
    padding: 35px 40px;
    border-radius: 16px;
    font-family: 'Poppins', sans-serif;
    box-sizing: border-box;
    width: 100%;
}

/* Individual Feature Item */
.yg-feature-item {
    display: flex;
    align-items: center; /* Centers the icon vertically with the text on desktop */
    gap: 18px;
}

/* Icon Styling */
.yg-feature-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0; /* Prevents the icon from squishing */
}

.yg-feature-icon i {
    font-size: 28px; 
    color: #9b5cff; 
}

/* Text Styling */
.yg-feature-content h3 {
    color: black; /* Fixed typo from 'blCK' */
    font-size: 15px;
    font-weight: 600;
    margin: 0 0 6px 0;
    line-height: 1.2;
}

.yg-feature-content p {
    color: #a0a0b0; 
    font-size: 13px;
    margin: 0;
    line-height: 1.5;
}

/* --- RESPONSIVE ADJUSTMENTS --- */
@media (max-width: 576px) {
    .yg-features-bar {
        padding: 30px 20px;
        gap: 35px; /* Slightly increased gap for vertical stack breathing room */
    }

    /* Stack the icon on top of the text and center everything */
    .yg-feature-item {
        flex-direction: column;
        text-align: center;
        gap: 12px; /* Thinner gap between icon and its text */
    }
}


