<script>
    document.addEventListener("DOMContentLoaded", function () {
        const headers = document.querySelectorAll(".cwa-header");

        headers.forEach(header => {
            header.addEventListener("click", function (e) {
                e.preventDefault(); // Prevents theme layout jumps
                const content = this.nextElementSibling;
                const isOpen = this.classList.contains("cwa-active");

                // Close all other accordion items automatically
                headers.forEach(otherHeader => {
                    if (otherHeader !== this) {
                        otherHeader.classList.remove("cwa-active");
                        const otherContent = otherHeader.nextElementSibling;
                        if (otherContent) {
                            otherContent.style.maxHeight = null;
                        }
                    }
                });

                // Toggle the clicked accordion item
                if (isOpen) {
                    this.classList.remove("cwa-active");
                    if (content) {
                        content.style.maxHeight = null;
                    }
                } else {
                    this.classList.add("cwa-active");
                    if (content) {
                        content.style.maxHeight = content.scrollHeight + "px";
                    }
                }
            });
        });

        // Re-calculate maxHeight for open items on window resize to ensure flawless responsiveness
        window.addEventListener("resize", function () {
            headers.forEach(header => {
                if (header.classList.contains("cwa-active")) {
                    const content = header.nextElementSibling;
                    if (content) {
                        content.style.maxHeight = content.scrollHeight + "px";
                    }
                }
            });
        });
    });
</script>				</div>
