<script>
document.addEventListener("DOMContentLoaded", function () {
    const toggles = document.querySelectorAll(".myg-faq-toggle-btn");

    toggles.forEach(btn => {
        btn.addEventListener("click", function (e) {
            e.preventDefault();
            
            const item = this.parentElement;
            const content = this.nextElementSibling;
            const isOpen = item.classList.contains("myg-faq-is-open");

            document.querySelectorAll(".myg-faq-accordion-item").forEach(otherItem => {
                if (otherItem !== item) {
                    otherItem.classList.remove("myg-faq-is-open");
                    otherItem.querySelector(".myg-faq-toggle-btn").setAttribute("aria-expanded", "false");
                    const otherContent = otherItem.querySelector(".myg-faq-panel-content");
                    if (otherContent) {
                        otherContent.style.maxHeight = null;
                    }
                }
            });

            if (isOpen) {
                item.classList.remove("myg-faq-is-open");
                this.setAttribute("aria-expanded", "false");
                if (content) {
                    content.style.maxHeight = null;
                }
            } else {
                item.classList.add("myg-faq-is-open");
                this.setAttribute("aria-expanded", "true");
                if (content) {
                    content.style.maxHeight = content.scrollHeight + "px";
                }
            }
        });
    });

    window.addEventListener("resize", function () {
        document.querySelectorAll(".myg-faq-accordion-item.myg-faq-is-open").forEach(activeItem => {
            const content = activeItem.querySelector(".myg-faq-panel-content");
            if (content) {
                content.style.maxHeight = content.scrollHeight + "px";
            }
        });
    });
});
</script>

